'use strict';

function evidenceInfo(id){const [mid,lid]=id.split('-'),material=materials.find(m=>m.id===mid),line=Number(lid?.slice(1));return {material,line,text:material?.lines[line-1]||''};}
function evidenceChips(r,readonly=false){return r.evidence.length?r.evidence.map(id=>{const e=evidenceInfo(id);return `<div class="evidence-chip"><p><strong>${esc(e.material?.id)} · L${e.line}</strong><br>${esc(e.text)}</p>${readonly?'':`<button aria-label="${esc(id)} 근거 연결 해제" data-action="evidence" data-evidence="${esc(id)}">×</button>`}</div>`;}).join(''):`<div class="evidence-empty">자료의 줄을 선택해 판단의 근거를 연결해 주세요.<br><button class="text-link" data-action="panel" data-panel="source">원본 자료 확인 ${arrow()}</button></div>`;}
function reviewPanel(){const r=review(),s=statements.find(s=>s.id===state.activeStatement),locked=state.challengeSubmitted;return `<section class="panel ${state.mobilePanel==='review'?'mobile-active':''}" data-panel="review"><header class="panel-header"><h2>${icon('link')}내 검토 <span class="muted small">${s.id}</span></h2><span id="review-state" class="pill ${r.saved?'':'neutral'}">${r.saved?'검토 저장됨':r.judgment||r.reason?'작성 중':'미검토'}</span></header><div class="panel-body"><div class="review-meta">${esc(s.text)}</div><fieldset class="plain-fieldset" ${locked?'disabled':''}><legend class="field-label">이 문장을 어떻게 판단했나요?</legend><div class="judgment-group">${Object.entries(judgments).map(([key,label])=>`<label class="judgment"><input type="radio" name="judgment" value="${key}" ${r.judgment===key?'checked':''}>${label}</label>`).join('')}</div></fieldset><div class="field-label">연결한 근거 <span class="optional">${r.evidence.length}개</span></div>${evidenceChips(r,locked)}<label class="field-label" for="review-reason">판단한 이유</label><textarea class="input-area" id="review-reason" maxlength="3000" placeholder="어떤 자료를 확인했고, 왜 이렇게 판단했나요?" ${locked?'readonly':''}>${esc(r.reason)}</textarea>${r.judgment==='correct'?`<label class="field-label" for="review-revision">수정한 문장</label><textarea class="input-area" id="review-revision" maxlength="3000" placeholder="근거에 맞게 문장을 다시 써보세요." ${locked?'readonly':''}>${esc(r.revision)}</textarea>`:''}<p id="review-error" class="form-error" role="alert"></p></div><div class="panel-action">${locked?`<a class="btn secondary block" href="#feedback">피드백으로 돌아가기 ${arrow()}</a>`:`<button class="btn primary block" data-action="save-review">${icon('check')}이 문장 검토 저장</button><p class="composer-note">작성 중에도 입력은 보존돼요. 저장하면 검토가 완료돼요.</p>`}</div></section>`;}
function challenge(){const count=savedReviews().length;return `<div class="container wide fade-in">${breadcrumb('결제는 왜 갑자기 느려졌을까?')}${stages(1)}<div class="workspace-top"><div><h1>이 판단, 근거가 충분할까요?</h1><p class="description">검산용 AI 초안을 문장별로 살펴보고, 원본 자료를 연결해 판단을 남겨주세요.</p></div><span class="pill outline">02 · 검산 챌린지</span></div>${state.challengeSubmitted?`<div class="review-readonly">${icon('lock')}제출한 검토입니다. 내용은 그대로 보관되며 변경할 수 없어요.</div>`:''}${mobileTabs('challenge')}<div class="work-grid">${sourcePanel(true)}<section class="panel ${state.mobilePanel==='statements'?'mobile-active':''}" data-panel="statements"><header class="panel-header"><h2>${icon('file')}검산용 AI 초안</h2><span class="pill neutral">별도 초안</span></header><div class="panel-body"><p class="statement-intro">내가 작성한 보고서와 다른 초안이에요.<br>문장을 선택하고 내 판단을 기록해 보세요.</p>${statements.map(s=>{const r=state.reviews[s.id];return `<button class="statement ${s.id===state.activeStatement?'active':''}" aria-pressed="${s.id===state.activeStatement}" data-action="statement" data-statement="${s.id}"><div class="statement-top"><span>${s.id}</span><span class="pill ${r?.saved?'':'neutral'}">${r?.saved?judgments[r.judgment]:r&&(r.reason||r.judgment||r.evidence.length)?'작성 중':'미검토'}</span></div><p>${s.text}</p></button>`;}).join('')}<p class="source-foot">${icon('info')}모든 문장을 의심하기보다, 자료가 판단을 뒷받침하는지 살펴보세요.</p></div></section>${reviewPanel()}</div><div class="progress-footer"><div class="progress-copy"><span><strong>${count} / ${statements.length}</strong> 문장 검토 저장</span><div class="meter" role="progressbar" aria-label="검토 저장 진행" aria-valuenow="${count}" aria-valuemin="0" aria-valuemax="4"><span style="width:${count/4*100}%"></span></div></div>${state.challengeSubmitted?`<a class="btn primary" href="#feedback">피드백 확인하기 ${arrow()}</a>`:`<button class="btn primary" data-action="submit-challenge">검산 제출하고 피드백 보기 ${arrow()}</button>`}</div></div>`;}
function resultCard(s){const r=review(s.id);return `<article class="review-result"><div class="review-result-head"><strong>${s.id}</strong><span class="pill">${judgments[r.judgment]}</span></div><p class="quote">${s.text}</p><p class="reason">${esc(r.reason)}</p>${r.judgment==='correct'?`<div class="guidance"><strong>내가 수정한 문장</strong><p>${esc(r.revision)}</p></div>`:''}<div class="evidence-links">${r.evidence.length?r.evidence.map(id=>`<button class="evidence-link" data-action="source-modal" data-evidence="${esc(id)}">${icon('link')}${esc(id.replace('-',' · '))} 근거 보기 ${icon('arrow')}</button>`).join(''):'<span class="small muted">연결한 원본 근거 없음</span>'}</div></article>`;}
function dimensionMap(final=false){const data=[['chat','요청 설계',state.messages.length?'대화 기록 있음':'미확인',state.messages.length?'예시 AI와 주고받은 요청을 남겼어요.':'아직 관찰할 대화 기록이 없어요.'],['link','근거 검증',`${evidenceCount()}개 근거 연결`,`${savedReviews().length}개 문장의 판단과 이유를 기록했어요.`],['file','문서화',final?(state.finalReport.trim()!==state.initialReport.trim()?'보고서 수정됨':'판단 유지'):'최초 보고서 보관',final?'최초·최종 제출 내용을 비교할 수 있어요.':'피드백 이전의 보고서가 보관되어 있어요.'],['sprout','판단 설명',final?'새롭게 관찰':'미확인',final?'되묻기 답변과 수정 이유를 남겼어요.':'다음 단계에서 생각을 설명해 볼 거예요.']];return `<section class="evidence-map" aria-label="학습 기록 지도">${data.map(([i,title,value,desc])=>`<div class="dimension"><div class="dimension-top">${icon(i)}<span class="pill neutral">${title==='판단 설명'&&!final?'미실시':'활동 기록'}</span></div><h3>${title}</h3><div class="dimension-value">${value}</div><p>${desc}</p></div>`).join('')}</section>`;}
function feedback(){return `<div class="container fade-in">${breadcrumb('1차 되짚 리포트')}${stages(2)}<div class="report-heading"><div><div class="eyebrow">첫 번째 되짚기</div><h1>내 판단의 근거를<br>한 번 더 살펴볼까요?</h1><p class="description">남긴 기록을 돌아보고, 다음 질문으로 생각을 이어가세요.</p></div><div class="report-seal">${icon('sprout')}</div></div><div class="notice">${icon('info')}<span>검토·보고서 기록은 방금 입력한 내용입니다. 아래 학습 안내는 화면 검토용 예시이며, 실제 AI 평가나 정오 판정이 아닙니다.</span></div>${dimensionMap()}<div class="report-grid"><div><section class="report-section"><div class="section-heading"><h2>내가 남긴 검토</h2><a class="text-link" href="#challenge">제출 내용 보기 ${arrow()}</a></div><p class="description">판단의 이유와 연결한 원문을 함께 살펴보세요.</p>${savedReviews().map(resultCard).join('')}<div class="guidance"><strong>다음에는 이렇게 확인해 보세요 · 안내 예시</strong><p>관찰한 현상과 원인에 대한 추론을 나누어 써보세요. 근거를 연결할 때는 지표의 값뿐 아니라 관찰 시간과 범위도 함께 확인하면 좋아요.</p></div></section><section class="report-section"><h2>처음 작성한 보고서</h2><p class="description">최종 보고서와 비교할 수 있도록 그대로 보관했어요.</p><div class="document-body original-doc">${esc(state.initialReport)}</div></section></div><aside><div class="next-card"><div class="eyebrow">다음 연습</div><h2>그 판단을,<br>내 말로 설명해 볼까요?</h2><p>두 가지 질문에 답하고 새로운 자료를 만나보세요. 처음의 보고서를 더 단단하게 만들 기회예요.</p><button class="btn lime block" data-action="begin-defense">${state.answersSubmitted?'보고서 수정 이어가기':'되묻기 시작하기'} ${arrow()}</button><span class="small">답을 서두르지 않아도 괜찮아요.</span></div></aside></div></div>`;}
function defense(){return `<div class="container fade-in">${breadcrumb('되묻기')}${stages(3)}<div class="question-layout"><aside class="question-aside"><div class="eyebrow">생각을 설명하는 연습</div><h1>왜 그렇게<br>생각했나요?</h1><p>내가 쓴 보고서를 떠올리며 답해보세요. 확신하는 부분과 아직 모르는 부분을 구분하는 것도 좋은 판단이에요.</p><svg class="aside-doodle" viewBox="0 0 180 150" fill="none" aria-hidden="true"><circle cx="86" cy="77" r="57" fill="#E5EFD9"/><path d="M40 45h98v67H92l-17 16v-16H40z" fill="white" stroke="#A6BA93" stroke-width="1.5" stroke-linejoin="round"/><path d="M72 65c0-14 24-16 26-1 2 10-12 12-12 23m0 8h.01" stroke="#55784B" stroke-width="3" stroke-linecap="round"/><path d="m143 31 7-6m-5 17 10-1" stroke="#95AD7C" stroke-width="2" stroke-linecap="round"/></svg><button class="text-link" data-action="report-modal">내 보고서 다시 보기 ${arrow()}</button></aside><div><div class="notice">${icon('info')}시안용 질문 2개입니다. 입력한 답변은 이 브라우저에 저장돼요.</div>${state.answersSubmitted?'<div class="review-readonly">제출한 답변입니다. 다음 단계에서 보고서를 수정해 주세요.</div>':''}<form id="defense-form"><div class="question-card"><span class="question-number">QUESTION 01</span><label for="answer-0">가장 확실한 사실과, 아직 가설인 부분은 무엇인가요?</label><p class="description">보고서에서 각각 하나씩 골라 근거와 함께 설명해 보세요.</p><textarea id="answer-0" class="input-area" maxlength="5000" placeholder="확실한 사실은… / 아직 가설인 부분은…" ${state.answersSubmitted?'readonly':''}>${esc(state.answers[0])}</textarea></div><div class="question-card"><span class="question-number">QUESTION 02</span><label for="answer-1">어떤 증거가 나오면 지금의 판단을 바꾸겠어요?</label><p class="description">내 가설을 지지하는 자료와 반박할 수 있는 자료를 생각해 보세요.</p><textarea id="answer-1" class="input-area" maxlength="5000" placeholder="이런 자료가 확인된다면 다시 생각할 것 같아요…" ${state.answersSubmitted?'readonly':''}>${esc(state.answers[1])}</textarea></div><p id="defense-error" class="form-error" role="alert"></p><div class="question-actions">${state.answersSubmitted?'':'<button type="button" class="quiet" data-action="sample-answers">답변 예시 넣기</button>'}<button class="btn primary" type="submit">${state.answersSubmitted?'보고서 수정으로 이동':'답변 저장하고 새 조건 확인'} ${arrow()}</button></div></form></div></div></div>`;}
function revise(){return `<div class="container fade-in">${breadcrumb('새 조건과 보고서 수정')}${stages(3)}<div class="workspace-top"><div><h1>새로운 정보로, 한 번 더 생각해 보세요.</h1><p class="description">판단을 바꿔도, 근거를 더해 유지해도 좋아요. 그 이유를 남겨주세요.</p></div><span class="pill outline">04 · 판단과 보고서 수정</span></div><section class="condition-box">${icon('spark')}<div><span class="pill amber">추가 자료 · UI 시안용 가상 메모</span><h2>결제 요청의 재시도 설정이 변경됐어요.</h2><p>운영팀은 12:02에 외부 결제 요청의 재시도 횟수가 1회에서 3회로 변경된 기록을 확인했어요. 당시 서버 자원 지표에는 큰 변화가 없었습니다. 이 정보만으로 인과관계가 확정되지는 않아요. 기존 가설과 어떤 관련이 있는지 생각해 보세요.</p></div></section><div class="two-column"><section class="panel"><header class="panel-header"><h2>${icon('lock')}처음 작성한 보고서</h2><span class="pill neutral">원본 보관</span></header><div class="panel-body"><div class="document-body original-doc">${esc(state.initialReport)}</div></div></section><section class="panel"><header class="panel-header"><h2>${icon('file')}다시 작성하는 보고서</h2>${state.completed?'<span class="pill">최종 제출됨</span>':'<button class="quiet" data-action="sample-revision">수정 예시 넣기</button>'}</header><div class="panel-body"><label class="sr-only" for="final-editor">최종 보고서</label><textarea id="final-editor" class="editor" maxlength="15000" ${state.completed?'readonly':''}>${esc(state.finalReport)}</textarea><div class="editor-footer"><span id="final-length">${state.finalReport.length}자</span><span class="save-state" id="final-save">${icon('check')}${storageAvailable?'저장됨':'브라우저 저장 불가'}</span></div></div></section></div><section class="revision-section"><label class="field-label" for="revision-reason">판단을 바꾸거나 유지한 이유</label><p class="editor-help">새로운 정보가 어떤 영향을 줬는지 적어주세요.</p><textarea id="revision-reason" class="input-area" maxlength="3000" placeholder="새 자료를 확인한 뒤, 내 판단은…" ${state.completed?'readonly':''}>${esc(state.reviseReason)}</textarea><p id="revision-error" class="form-error" role="alert"></p></section><div class="revision-actions"><span class="small muted">${icon('shield')}최초 보고서는 그대로 보관돼요.</span>${state.completed?'<a href="#final" class="btn primary">최종 리포트 보기 →</a>':'<button class="btn primary" data-action="submit-final">최종 제출하고 변화 확인하기 '+arrow()+'</button>'}</div></div>`;}
function finalReport(){const changed=state.initialReport.trim()!==state.finalReport.trim();return `<div class="container fade-in">${breadcrumb('최종 되짚 리포트')}${stages(4)}<section class="completion-banner"><div><div class="eyebrow">한 번의 연습, 남겨진 생각</div><h1>풀고, 확인하고,<br>다시 생각하는 연습을 마쳤어요.</h1><p>처음의 판단과 지금의 판단을 나란히 살펴보세요.</p></div><div class="report-seal">${icon('check')}</div></section><div class="notice">${icon('info')}화면 체험용 완료 기록입니다. 작성 내용의 변화와 수행 여부를 보여주며, 실력 점수나 실제 AI 평가를 의미하지 않습니다.</div>${dimensionMap(true)}<section class="report-section"><div class="section-heading"><h2>내 보고서는 어떻게 달라졌을까요?</h2><span class="pill">${changed?'내용이 변경됐어요':'판단을 유지했어요'}</span></div><p class="description">직접 작성한 최초·최종 보고서를 비교해 보세요.</p><div class="two-column"><section class="panel"><header class="panel-header"><h2>처음의 보고서</h2><span class="pill neutral">INITIAL</span></header><div class="panel-body"><div class="document-body original-doc">${esc(state.initialReport)}</div></div></section><section class="panel"><header class="panel-header"><h2>마지막 보고서</h2><span class="pill">FINAL</span></header><div class="panel-body"><div class="document-body">${esc(state.finalReport)}</div></div></section></div><div class="guidance"><strong>내가 남긴 수정·유지 이유</strong><p class="preserve-text">${esc(state.reviseReason)}</p></div></section><div class="two-column"><section class="report-section"><h2>새롭게 남긴 판단의 기록</h2>${state.answers.map((a,i)=>`<div class="review-result"><span class="question-number">QUESTION 0${i+1}</span><p class="reason">${esc(a)}</p></div>`).join('')}</section><section class="report-section"><h2>다음 연습에 가져갈 습관</h2><p class="description">학습 안내 예시</p><div class="mini-step"><span>01</span><div><strong>사실과 해석을 나눠 쓰기</strong><p>확인한 내용과 추론한 내용을 구분해 보세요.</p></div></div><div class="mini-step"><span>02</span><div><strong>판단 옆에 근거 남기기</strong><p>다른 사람도 확인할 수 있는 원문을 연결해 보세요.</p></div></div><div class="mini-step"><span>03</span><div><strong>새로운 정보에 열린 결론 쓰기</strong><p>무엇을 더 알면 판단을 바꿀지 생각해 보세요.</p></div></div></section></div><div class="report-footer-actions"><a class="btn primary" href="#learning">내 학습으로 돌아가기 ${arrow()}</a><button class="btn secondary" data-action="export-notes">내 작성 기록 보기 ${icon('file')}</button></div></div>`;}
function learning(){return `<div class="container fade-in"><div class="learning-header"><div class="eyebrow">나의 연습을 이어가는 곳</div><h1>조금씩, 더 단단한 판단으로.</h1><p class="description">풀던 문제를 이어서 풀고, 남겨둔 생각을 다시 확인해 보세요.</p></div><div class="learning-summary"><div><strong>${state.started&&!state.completed?1:0}</strong><span>진행 중인 문제</span></div><div><strong>${state.completed?1:0}</strong><span>완료한 문제</span></div></div>${state.started?`<div class="section-heading"><h2>${state.completed?'완료한 학습':'이어서 학습하기'}</h2><span class="pill">${progressLabel()}</span></div><div class="explore-grid"><div>${problemCard()}</div><aside class="learning-note"><h3>내 기록은 여기 있어요.</h3><p class="description small">작성한 보고서와 검토 내용은 이 브라우저에 저장돼요. 완료한 학습에서는 최초·최종 보고서를 다시 확인할 수 있어요.</p><button class="quiet" data-action="reset" style="margin-top:22px">처음부터 다시 연습하기 ${icon('refresh')}</button></aside></div>`:`<div class="empty-state">${icon('sprout')}<h2>첫 번째 연습을 시작해 볼까요?</h2><p>문제를 풀며 남긴 생각과 근거가 여기에 모여요.</p><a class="btn primary" href="#explore">문제 만나러 가기 ${arrow()}</a></div>`}</div>`;}
